import{overlaps}from"/js/modules/Knowbase/CommentAnchor.js";function isFormattingWhitespace(t){if(t.nodeValue.trim()!==""){return false}const e=t.parentElement;if(e===null){return false}return[...e.children].some(t=>!/^(inline|contents)/.test(getComputedStyle(t).display))}export function buildDomTextIndex(t){const e=[];let n="";const o=document.createTreeWalker(t,NodeFilter.SHOW_TEXT);let s=o.nextNode();while(s){if(!isFormattingWhitespace(s)){const t=n.length;n+=s.nodeValue;e.push({node:s,start:t,end:n.length})}s=o.nextNode()}return{text:n,segments:e}}function boundaryToOffset(t,e,n,o){const s=t.segments.find(t=>t.node===e);if(s){return s.start+n}const r=document.createRange();r.setStart(e,n);r.collapse(true);let a=null;for(const e of t.segments){if(o){if(r.comparePoint(e.node,e.node.length)<=0){a=e.end}}else if(a===null&&r.comparePoint(e.node,0)>=0){a=e.start}}return a}export function domRangeToOffsets(t,e){const n=boundaryToOffset(t,e.startContainer,e.startOffset,false);const o=boundaryToOffset(t,e.endContainer,e.endOffset,true);if(n===null||o===null||n>=o){return null}return[n,o]}export function wrapOffsetsInMarks(t,e,n,o){for(const{segment:s,start:r,end:a}of overlaps(t.segments,e,n)){const t=document.createRange();t.setStart(s.node,r-s.start);t.setEnd(s.node,a-s.start);const e=document.createElement("mark");e.className="kb-comment-highlight";e.dataset.commentId=String(o);e.setAttribute("role","button");e.setAttribute("tabindex","0");e.setAttribute("aria-label",__("View comment"));t.surroundContents(e)}}